@dataclass(frozen=True)
class Money:
    amount_in_minor_units: int
    currency: str

    @staticmethod
    def of(amount: int, currency: str) -> "Money":

def __post_init__(self) -> None:
    if not self.normalized_query or not self.normalized_query.strip():
        raise ValueError("ProductSearchSpec.normalized_query required")
    # top_k 由调用方保证为正

def __post_init__(self) -> None:
    if not self.sku_id:
        raise ValueError("Sku.sku_id required")
    if self.stock < 0:
        raise ValueError(f"Sku.stock 必须非负：{self.sku_id}")

def add(self, other: "Money") -> "Money":
    self._assert_same_currency(other)
    return Money(self.amount_in_minor_units + other.amount_in_minor_units, self.currency)

def convert(self, money: Money, to_currency: str) -> Money:
    if to_currency == money.currency:
        return money
    if to_currency not in SUPPORTED_CURRENCIES:
        raise ValueError(f"Money.currency 不受支持：{to_currency}")
    converted_minor = round(money.amount_in_minor_units * self.rate(money.currency, to_currency))
    return Money.of(converted_minor, to_currency)

